  "test": "import logging\nimport pytest\nimport httpx\nfrom langfuse.api.core.http_response import HttpResponse\n\ndef test_http_response_close_logs_debug(caplog):\n    # Create a simple HTTPX response with known status code\n    response = httpx.Response(202, request=httpx.Request(\"GET\", \"http://example.com\"))\n    http_resp = HttpResponse(response, data=None)\n    with caplog.at_level(logging.DEBUG):\n        http_resp.close()\n    # Verify that a debug log containing the status code was emitted\n    assert any(\"Closing HTTP response with status 202\" in record.message for record in caplog.records)\n"
